# Experiment 3H: compare student marks with grouped bars.
source("r/Experiment-03/common.R"); library(ggplot2); library(tidyr); d<-load_students(); long<-pivot_longer(d,cols=all_of(subjects),names_to="Subject",values_to="Score"); p<-ggplot(long,aes(Student,Score,fill=Subject))+geom_col(position=position_dodge(.82),width=.72)+scale_fill_brewer(palette="Set2")+scale_y_continuous(limits=c(0,100),breaks=seq(0,100,20))+labs(title="Subject Scores by Student",x="Student",y="Score",fill="Subject")+theme_minimal()+theme(axis.text.x=element_text(angle=35,hjust=1),legend.position="bottom"); ggsave(save_plot_path("3H_grouped_bar_chart.png"),p,width=10,height=5.5,dpi=180); print(p)
